        "passageZh": "从前，一户人家的菜园里有一块大石头，大约宽40 厘米，高10 厘米。到菜园的人，不小心就会踢到那块大石头，不是跌倒就是擦伤。儿子问：“爸爸，那块讨厌的石头，为什么不把它挖走？”爸爸回答：“你说那块石头吗？从你爷爷那时起，它就一直在那里了，它体积那么大，不知道要挖到什么时候，不如走路小心一点儿。”后来，儿子娶了媳妇，这块大石头还在那里。有一天，媳妇气愤地说：“爸爸，菜园里那块大石头，真是很碍事，改天请人搬走好了。”爸爸回答说：“算了吧！那块大石头很重的，可以搬走的话，我早就搬走了，哪会让它留到现在啊！”媳妇心里非常不是滋味，那块大石头不知道让她跌倒多少次了。有一天早上，媳妇带着锄头和一桶水来到菜园，将整桶水倒在大石头的四周。十几分钟以后，媳妇开始用锄头挖大石头四周的泥土。媳妇早有心理准备，可能要挖一天吧，没想到，几分钟就把石头挖起来了，看看大小，这块石头没有想象的那么大，都是被那个巨大的外表欺骗了。",
