        "kind": "mcq",
        "passageZh": "这天，村里来了一个陌生人。他告诉村民，他将以每只100 元的价格收购猴子。村民开始去附近的森林里捕捉猴子。收猴人收购了几千只猴子，当猴子的数量减少时，村民们停止了捕捉。这时，收猴人放出话来，每只猴子的收购价提高到200 元，这个价格是原来的两倍，村民又重新投入到抓猴的行动中。不久，猴子的数量更少了，村民再次停止抓猴，于是收猴人把每只猴子的收购价提高到250元。但这时森林里的猴子已经很少了，村民努力一天，也很难抓到一只猴子，大家渐渐都没了积极性。收猴人把收购价提高到500 元。不过，他说自己有急事，先回城了，收购猴子的事由他的朋友来处理。收猴人回城后，他的朋友指着已被老板收购到的几千只猴子对村民说：“我们来做一笔买卖吧，我以每只猴子350元的价钱卖给你们，等我朋友从城里回来，你们再以每只500 元的价钱卖给他。”村民们拿出所有的钱买下了所有猴子，但此后，他们再也没见过收猴人和他的朋友，森林里又到处都是猴子的身影„„\n看了这则故事，你对某些股票是怎么回事，或许会有一个很好的认识吧。",
