        "kind": "mcq",
        "passageZh": "在我的家乡，有一个专卖小吃的饭馆儿，名字叫“四个点儿”，老板的解释是：环境好点儿、菜好吃点儿、您常来点儿、我高兴点儿。每天都有很多人在那里排队，有些人还会因为排不上，只好带着遗憾离开。这家饭馆儿有个很奇怪的规定，一天的营业时间只是从上午10点到下午两点，只有短短的4 小时，其他时间都不开放，而且不能预订。但就是这4 小时，每个月小店的收入也不下5 万元。谈起开店的秘密，店主人是这样说的：现在做的菜，味道其实和刚开业的时候一模一样，什么也没有改变，改变的只是经营的方式。刚开始的营业时间是\n12 个小时，从早上8 点到晚上8 点，可是生意却不太好，一来是因为知道这个地方的人很少，二来是因为菜的种类很多，反而显得没特点。所以我决定删掉几个种类，只做几种有特点的小吃。然后在经营时间上做了调整，一天只营业4\n小时。人们都有好奇心理，越是不容易买到的东西就越想买。果然，这两种办法使饭馆儿的生意越来越好。很多人不得不早早去那里排队，生怕错过了吃到美味的机会。",
