        "passageZh": "真诚的微笑透出的是宽容，是善意，是温柔，是爱意，更是自信和力量。微笑是一个了不起的表情，无论是你的客户，还是你的朋友，甚或是陌生人，只要看到你的微笑，都不会拒绝你。有一位老太太退休后开了一家心理咨询所，生意非常红火，预约的号甚至排到了几个月以后。有人问她，她如此受欢迎的原因是什么。老太太说，其实很简单，她的主要工作就是让每一位上门的咨询者经常学习一门功课：寻找微笑的理由。比如，在你下班的时候，爱人给你倒了一杯水；下雨的时候，你收到家人发来的让你注意安全的信息；在电梯门将要关上时，有人按住按钮等你赶到；清洁工在离你几步远的地方停下扫帚，而没有让你奔跑着躲避灰尘„„诸如此类的生活细节，都可以作为微笑的理由，因为这是生活送给你的礼物。那些按老太太的要求去做的人发现，几乎每天都能轻而易举地找到十来个微笑的理由。时间长了，夫妻间的感情开始慢慢好转；与上司或同事的紧张关系趋向缓和；日子过得不开心的人也会期待明天新的太阳。总之，他们付出的微笑，都有了意想不到的收获。美丽的笑容，犹如初开的桃花，给人甜美的感觉。如果能恰当地运用微笑，就可以传递情感，沟通心灵，甚至战胜对手。",
