        "audioZh": "父亲邀请我一同到林间散步，我高兴地答应了。父亲在一个拐弯处停了下来，在短暂的沉默之后，他问我：“除了小鸟的歌唱之外，你还听到了什么？”我仔细地听，几秒种之后我回答他：“我听到了马车的声音。”父亲说：“对，是一辆空马车。”我问他：“我们又没看见，您怎么知道是一辆空马车？”父亲答道：“从声音就能判断出是不是空马车，马车越空，声音就越大。”后来我长大成人，每当我看到自以为是、目空一切、看不起别人、粗暴地打断别人的人，我都感觉好像是父亲在我耳边说“马车越空，声音越大”。 问：父亲邀请儿子去做什么？",
