        "kind": "mcq",
        "passageZh": "下班时正是车流量高峰，你急着赶一个约会。从办公室走到地铁站需要15\n分钟，于是你决定打车。\n10 分钟过去了，没有一辆出租车停在你的面前，你决定继续等待。15 分钟后，你开始烦躁不安。但通常你还会继续等下去，因为已经等了这么久，你心存侥幸：或许再多等一分钟，车子就会来。可直到半个小时后，你仍然站在马路上等待，你感到万分后悔——早知道这样，就该选择步行15分钟去地铁站。这样的情况，估计大多数人都经历过。无法放弃已经付出的时间，结果投入了更多的时间。这与投资中的“套牢”多么相似啊：已经亏损了，却没有及早卖出，结果赔了更多。很多投资者在进行某项投资时，最先想到的往往是能赚多少，而不是会亏多少。殊不知，事实上，必须为每一笔买卖事先定一个“止损线”，“止损线”可能就是你的生命线。我们必须要先学会如何输钱，这比学会如何赢钱更为重要。即使你只搞对一半，你也是赢家，关键在于每次搞错的时候，要将损失减到最少。",
        "passagePy": "",
        "passageVi": "",
        "q": "定“止损线”的目的是：",
