        "passageZh": "一个小男孩儿问奶奶：“您在写什么？”奶奶停下手中的笔，对孙子说：“我在写你的事情。你看到奶奶手中的这支铅笔了吗？奶奶希望你长大后，也能像这支铅笔一样。”奶奶的话激起了小男孩儿的好奇心：“它和我见过的铅笔都一样啊。”“孩子，这支铅笔有5 个特性。如果你也能具备这5 个特性，那你将成为一个很了不起的人。”奶奶说。“铅笔的第一个特性是，尽管你能做很多大事，但你千万不能忘记，那是因为一直有一只手在引导着你。“铅笔的第二个特性是，有时我们不得不停下来，用铅笔刀削一削它。这样虽然会使铅笔经历痛苦，但是削过之后，它会变得更加尖利。所以，孩子，你也必须学会忍受痛苦和悲伤，因为它们能使你成为一个更优秀的人。“铅笔的第三个特性是，它允许我们使用橡皮擦掉错误。这就是说，改正我们做过的一些错事并不是坏事，它可以帮助我们走上正确的道路。“铅笔的第四个特性是，真正有用的不是漂亮的笔杆，而是里面的铅芯，所以要重视你的内心世界。“最后一点，无论如何，它总是会留下自己的印迹。在人生旅途中，你所做的任何事情也会留下印迹。所以，今后无论你做什么，都要先考虑清楚后果。”",
