        "passageZh": "一位老师傅在退休时反复告诉自己的学生：“无论何时，你都要少说话、多做事，要有真本领。”学生听了连连点头。\n10年后，那个学生来找师傅，苦着脸说：“师傅，我一直都是按照您说的方法做的，每天埋头苦干，不但为工厂干了许多实事，也学到了一身好本领。可是，那些技术比我差、资历比我浅的人都升职、加薪了，而我还是拿着过去的工资。”师傅说：“你确定你在工厂里的位置已经无人能代替了吗？”他点了点头：“是的。”师傅说：“不管你用什么理由，你一定得请一天假。因为，一个灯如果一直亮着，那么就没人会注意到它，只有关上一次，才会引起别人的注意„„”他明白了师傅的意思，请了一天假。果然，第二天上班时，厂长找到他，说要让他当全厂的总工程师，还要给他涨工资。原来，在他请假的那一天，厂长发现工厂完全离不开他，因为平时很多问题都是他去处理的，别人根本不会。之后，只要感觉自己不被重视，他便要请上一天假。每次请假后，厂长都会给他加工资。然而，就在他又一次请假后去上班时，他被门卫拦在了门外，“厂长说你不用来上班了。”他苦恼地去找师傅：“师傅，我都是按您说的去做的啊。”师傅说：“那天，你只听了一半。”他连忙问：“那另一半是什么？”师傅说：“要知道，一个灯如果一直亮着，确实没人会注意到它，只有关一次才会引起别人的注意。可是如果它总是不亮，那它就会有被取代的危险，谁会需要一个一会儿亮一会儿又不亮的灯呢？”",
