        "passageZh": "一位拳击手参加比赛，他认为自己一定可以夺得冠军。出乎意料的是，在最后的决赛中，他遇到了一个实力相当的对手。比赛进行了一半，拳击手意识到，自己竟然找不到对方的弱点，而对方却往往能找到自己的漏洞。比赛的结果可想而知。他生气地找到自己的教练，将对方和他比赛的过程再次演示给教练看，并请求教练帮他找出对方的弱点。他决心根据这些弱点，苦练出足以打败对方的新招，好在下次比赛时打倒对方，夺回冠军的奖杯。教练笑而不语，在地上画了一条线，要他在不擦掉这条线的情况下，让这条线变短。拳击手思来想去，最后也没有什么办法，不得不再次向教练请教。教练在原先那道线的旁边，画了一道更长的线。两者比较，原来的那条线，确实显得短了许多。这时教练开口道：“夺得冠军的关键，不仅在于攻击对方的弱点，更在于自己的强大。正如地上的长短线一样，只有你自己变得更强，才更有机会赢。如何使自己更强，才是解决问题的根本。”",
