        "partLabel": "Phần 3 • Đọc hiểu bài văn dài chọn đáp án (71–90)",
        "kind": "mcq",
        "passageZh": "中国古时候有一个很有学问的人，名叫孔融，是孔子的后代。他从小就很聪明，小小年纪，已在社会上享有盛名。他10岁时，跟他父亲到洛阳去拜访有名的李元礼。李元礼只接待自己的亲戚和有名的人。于是，孔融对守门人说：“我是李太守的亲戚，请给我通报一下。”守门人通报后，李太守接见了他。李元礼问他：“请问你和我是什么亲戚关系呢？”孔融回答道：“从前我的祖先孔子是你家祖先老子的学生，因此，我和你也算是世交呀！”当时在座的人对孔融的这一番话都很惊奇。其中有一位客人来晚了，在座的人将孔融的话告诉他后，他随口说道：“小时候很聪明，长大后就不一定了。这就是小时了了，大未必佳。”聪明的孔融立即说：“我想你小的时候，一定是很聪明的。”这个人半天说不出话来。后来，人们便用“小时了了，大未必佳”来说明小孩子从小聪明，懂得很多事情，但长大后却未必能够成材。一个小孩子，先天聪明自然是好的，但若无后天的培养和努力，也会变成一块无用的材料。很多人因为自己生性聪明，不肯好好学习，聪明反被聪明误，长大后反而变成最无用之人。",
