        "passageZh": "一位作家高中二年级的时候，在学校的表现很差，许多老师对他已经不抱什么希望了。但他的语文老师却很重视他，老师告诉他：“我教了50 年书，一眼就看出你是个能成大器的学生。”作家被这句话感动和震撼了。为了不辜负老师的一片苦心，他从此发奋努力，决心做一个对社会有用的人。有趣的是，十几年后，当时是记者的他，在采访一个小偷时，有感于小偷思维之缜密，作案手法之细腻，情不自禁地对那个年轻人说：“你思维如此细密，手法那么灵巧，做任何一行都会有成就的。”他不曾想到，\n20 年后，当年的小偷成了一位很有名气的企业家。有一次，当年的小偷碰到了作家，这位如今的老板真诚地对作家说：“您对我说的话点亮了我生活的希望，它使我想到，除了做小偷，我还可以做其他正经的事。”一句话的力量有多大？作家的经历告诉我们：一句话可以成为温暖他人一生的阳光，能给他人一辈子的温暖和明亮。",
