        "passageZh": "暑假，我陪朋友一家三口去爬梅岭。爬到半山腰的时候，一只小飞虫钻进了我左耳朵，弄得我难受极了。我的钥匙上正好有一根银质的掏耳勺，我决定用它置“闯入者”于死地。就在我小心翼翼地把小掏耳勺伸入耳孔的时候，朋友却拦住了我，说：“你这样做是把飞虫往耳朵深处赶，一旦钻到更深的地方，就麻烦了。”朋友的话似乎有道理，可是我该怎么办？朋友的爱人是个医生，她建议道：“你可以往左耳滴一两滴油，这样就可以把飞虫粘住。等耳朵里没动静了，再用少量温水冲洗耳朵，最后要用棉签吸干耳道里的水，这样干净又卫生。”可是朋友的小女儿多多不高兴了，她对妈妈说：“小飞虫不是故意让叔叔痛的，它一定是在叔叔的耳朵里迷路了。”一会儿，小姑娘对我说：“叔叔，我有办法了。”说着，她让我把头低下来，右耳朵贴在石桌上，她自己站到了石凳上，用她的小手电筒对着我的左耳朵照。我一时找不到油、棉签和温开水，也只好让小姑娘摆布。很快，我的耳朵就不痛了。多多和她的父母惊喜地看到一只小飞虫从我的耳朵里飞了出来，飞到手电筒的亮光里。对待一只在黑暗中迷路而让你难受的飞虫，其实不必太心急，更不必只想着惩罚和消灭，而要想办法给它一个光明的方向，给它一个投奔光明的机会。",
        "passagePy": "",
        "passageVi": "",
