        "partLabel": "Phần 3 • Đọc hiểu bài văn dài chọn đáp án (71–90)",
        "kind": "mcq",
        "passageZh": "一个明智的商人，在选择销售的商品时，一定不会选择自己所偏好的东西，而是卖自己不喜欢的东西。为什么呢？原来，一般人对自己喜欢的东西都会有强烈的占有欲。这是人的本性，很难控制，即使控制得住，也是要付出感情代价的。所以，真正的生意人卖自己所不喜欢的东西。比如，不喜欢古董的人卖古董，不喜欢珠宝的人卖珠宝。原因很简单，只有卖自己不喜欢的东西，才会想办法尽快把它卖出去。否则，压在那儿对自己没有益处，反而是一种浪费。在生意场上，那些卖珠宝的商人，大多数是对珠宝没有偏爱的人。珠宝一般对女性最有吸引力，通常是女人们喜爱的东西，所以珠宝商很少是女性，大多数是对珠宝毫无偏爱的男士们。同样，那些做服饰的商人也大多是男性。一位商人分析，正是因为他们所卖的不是自己喜欢的商品，所以在购进商品时，总是能做出比较客观、全面的分析，而不会因为自己的喜好而忽略了其他人的需求。只有这样，才可能获得更大的利润。",
