        "audioZh": "女：大山先生，《人民日报》曾这样评价您：“大山虽然是外国人，但不是外人。”中国人从来都没把您当外人看，您是怎样评价自己的呢？ 男：我觉得我是最中国化的外国人和最为中国人熟知的外国人。 女：按照我们节目的惯例，请您先简单地做个自我介绍吧。 男：自我介绍吗？我觉得大家对我的基本情况还是比较熟悉的。但有个问题很重要，也困扰我很久了，就是如何给自己定位。 女：如何给自己定位？ 男：对，很多人问我，你到底是干什么的？或者干脆把我归类为相声演员。其实我最初的想法不是这样的，现在的奋斗目标也不仅仅是这样的。我一九八四年开始学习中文，四年后获得奖学金，参加学者互换交流项目来到中国北京。在学习中文的四年中，我对中国的文化、历史等基本情况就已经略知一二，但没有亲身感受，所以来中国就一个目的：深入中国，体验书本上学习不到的中国。 女：也就是说相声并不是您的专业领域？ 男：是的，来中国，是希望多了解东方文化、中国文化，希望自己能够在中西文化之间做一个桥梁。当时的想法也不是很清楚，到底在哪一个领域发展，外交？商业？文化？学术？没有明确的目标。然而，一九八八年一个偶然的机会，在中央电视台的春节联欢晚会上演了一个节目，大山的名字就是从那个节目中来的。从那时起我才开始接触相声这种中国传统的艺术表演方式。尽管很多观众对我的认识主要是通过这样一个渠道，但我始终都不是一个专业的相声演员，也不靠这个谋生。我给自己的定位是文化的使者，相声演员对我来讲只是手段而已。 女：其实，在节目刚开始时我也觉得特别为难，您在教育、公益、商业等多个领域都成绩显著，我都不知道该如何向观众介绍您了。 男：你可以说我是一个自由职业的文化使者，我所从事的工作不管在哪个领域都离不开文化，只要能够促进中西方之间的交流和相互了解，我都挺感兴趣的，都特别喜欢做。 问：男的为哪个问题所困扰？",
