        "audioZh": "女：您好！观复博物馆是我国第一家私立博物馆，作为它的创办人，您能不能谈一下博物馆是如何实现盈利的呢？ 男：观复博物馆现在的运营模式主要有三部分。第一部分是门票收入，每张门票五十元。我考察全世界博物馆门票的收费标准，大致和当地电影院票价差不多。我们把观复博物馆的门票设计成了六个样子，参观者可以自愿选择任意一种。大家都把门票作为纪念品保存，在我们的垃圾箱里看不到丢弃的门票。虽然每个人的参观成本大约是一百五十元，我们只收五十元，但我依然认为每个买票参观的人都是我们的赞助人。第二部分收入，是我们提供的各种服务，包括鉴定、讲解、场地租用等。第三部分收入来自我们的品牌输出，把无形资产变成有形财富。 女：除了每年的大年三十至大年初三这四天，博物馆全年都开放，是这样的吗？ 男：是的。其实从成本上讲，闭馆更省钱，但我们考虑的不是这个。现在每天都不断有观众来参观，最多的时候达到几百人。观复博物馆不能让大老远前来参观的人失望。 女：听说您还准备建新的观复博物馆，您对新馆有什么设想呢？ 男：未来的观复博物馆会有非常好的设计，满足观众的乐趣。现在观复博物馆五千平方米，以后至少应该达到两万到三万平方米；公共交通要非常便捷，要具备高品质的展览；还要有充足的休息空间，让每个参观者都非常愉快。比如有些人会参观一整天，要有餐饮和休息的区域，最低标准要有免费的饮用水。我还要建一个文化庭院，给每个为博物馆做出重要贡献的人做一个真人大小的铜像。 女：您有那么多的想法，为什么还准备把观复博物馆捐出呢？ 男：我希望能够把博物馆交给社会管理，使其社会化，成为社会公共财富。另外，我的晚年想过得清净一些，不再负责博物馆的经营和管理。退下来以后，我很希望能腾出时间再多写些书。 问：关于门票，下列哪项正确？",
        "audioPy": "",
        "audioVi": "",
        "opts": [
          "卖150 元",
          "比电影票贵",
          "被设计成6 种样子",
          "一个月内可多次使用"
        ],
        "ans": 2,
        "exp": "Đề thật H61110 Câu 22 → Đáp án C (被设计成6 种样子)."
