        "prompt": "Nghe đoạn câu 31 và chọn đáp án đúng: 发现敌机俯冲下来时，将军是怎么做的？",
        "statement": "",
        "statementPy": "",
        "audioZh": "在一场激烈的战斗中，将军忽然发现一架敌人的飞机向阵地俯冲下来。按照常理，发现敌机俯冲时要毫不犹豫地卧倒。可是将军并没有立刻卧倒，因为他发现离他四五米远处有一个士兵没有注意到敌人的飞机，只顾前进与敌人搏斗。他顾不上多想，一个跳跃将士兵扑倒在地，紧紧地压在了身下。就在此刻，一声巨响，敌人飞机上的炮弹坠落、爆炸，飞溅起来的泥土纷纷落在他们的身上。待四周逐渐平静下来，将军拍拍身上的泥土，回头一看，顿时惊呆了：刚才自己所处的那个位置已经被炸出一个大坑，如果刚才自己没有保护士兵而原地卧倒，那么现在留在大坑里的就是自己的尸体。 问：发现敌机俯冲下来时，将军是怎么做的？",
