        "audioZh": "在长白山的茫茫林海中穿行，常常会看到这样一个奇怪的现象：稀疏生长或者独自生长的树木，树身都不会太高，而且它们的枝干也弯曲不直。但成片集中生长的树木则每一棵都高大挺拔，从不旁逸斜出。阳光、水分是树木生存发展必需的条件，按照这个道理，占有阳光、空间多的树木，一定会比那些头顶上只有巴掌大一块儿天的树木要长得好。但为什么生存环境优越的树木反而没有环境恶劣的树木高大？对于这个问题，当地人是这样解释的：树也如同人一样，单独生长的树木因为不存在竞争，就会变得懒散、随意，这往往使它们长得奇形怪状；而集中长在一起的树木，每个个体想要生存，都必须让自己长得高大强壮，才能争得有限的阳光、水分等资源，从而存活下来，最终长成了栋梁之材。可见，竞争往往是让生命自强不息的最好方法。 问：成片生长的树木有什么特点？",
