        "audioZh": "在生活中，有很多这样的朋友，在你遭遇困难时，虽然在尽力帮助你，但没办到之前绝不会告诉你他在帮你，甚至有时候还故意疏远你，等到终于办成了才会告诉你，想给你一个惊喜，甚至有的人连惊喜都不给你，做好事不留名。不能不说，这种人是好人，我们的社会也往往把这种行为归为品德高尚。不居功，更不邀功，这确实很难得。但是，当你的朋友有困难，而你又确有能力帮他时，不妨让他知道有人在帮他。对于身处困境的人来说，这至少是一种安慰。这时候你给予他的关心，会让他更有希望、更有信心去面对困难。人的忍耐力是有限度的。有人曾做过统计，我们对一个人或一件事的忍耐极限平均为四十六天。也就是说，如果你连续四十六天不理我，那你第四十七天就再也别指望我会理你了。去年我女朋友要过生日时，我提前一个月告诉她要给她庆祝生日，她整整幸福了一个月，天天都生活在兴奋和期待中。她对我的做法非常满意。我想，要是事先没告诉她，甚至有意冷落她，让她先忍受一个月的失落，只为了最后那一刻给她一个惊喜，那她还会欣然接受我这样的惊喜吗？我真的不敢确信她能忍受我一个月，真庆幸没有那么做。 问：有能力帮助朋友时，最好怎么做？",
