        "audioZh": "市场上毒蛇的价格总是比无毒蛇的售价更高，捕蛇的人认为这除了毒蛇比无毒蛇的药用价值更高外，还有一个原因，那就是毒蛇更稀少。这让人很难理解，在蛇的世界里，毒蛇是强者，按说，它应该比无毒的蛇更容易生存，为什么数量反而更少呢？经常捕蛇的人说：“遇到一条蛇，看它有毒无毒，只要看它的行为就知道了，无毒的蛇一般看到人就逃，而毒蛇看到人不但不逃，反而迎上前去攻击人。”正因为毒蛇有“毒”这个强大的武器，所以才什么都不怕，处处攻击别人，侵害别人。然而，正是由于它们处处树敌，处处作恶，同时也遭到了别人的反击、报复和捕杀。目前，毒蛇的数量越来越少，有的甚至到了濒临灭绝的边缘。这样看来，作恶看似伤害的是别人，实则伤害的却是自己。 问：这段话主要想告诉我们什么？",
