        "passageZh": "一个富商花费巨资收藏了许多珍贵的古董和字画，还有各种珍珠、翡翠。他将这些东西放在公司的大厦里，为防止失窃，他还安装了严密的保安系统，（71）。有一天，富商忽然心血来潮，决定让大厦的清洁工进去开开眼界。清洁工进去后，（72），只是慢慢地逐一浏览。富商忍不住炫耀地说：“怎么样，看了这么多的好东西，不枉此生了吧？”清洁工静静地说：“是啊，我现在感觉与你一样富有，而且比你更快乐。”（73）。“我拥有的宝物你一件都没有，你怎么能和我一样甚至比我更快乐呢？”“你所有的宝物我都看过了，不就与你一样富有了吗？而且我不必为这些东西担心这担心那，岂不比你更快乐？”能够欣赏，常常比拥有更快乐。（74），你自私时，它便已经停止流通了。你关上门，使快乐无法流向你，困守在自设的真空中不肯接受也不愿意付出，结果很可能是窒息。而当你敞开心胸，乐于付出的同时，（75）。",
