        "passageZh": "人生来就会笑，但很少有人知道，笑也是一种很好的健身运动。研究证明，笑与人们的健康有着十分密切的关系。每笑一声，从面部到腹部约有80块肌肉参与运动，（76）。一天中你如果笑了100 次，对心脏的血液循环和肺功能的锻炼，（77）。笑还是一种有效地深呼吸运动和腹肌运动，开怀大笑有助于呼吸和消化。总之，人的许多器官都能从笑的“震撼”中获益，（78）。此外，笑可以使人延缓衰老。俗话说得好：“笑一笑,\n十年少。”此话有其生物学道理。当你笑的时候，大脑神经会放松一会儿，从而使大脑有更多的休息时间，因而延缓衰老。同时，（79），因为笑的时候,脸部肌肉会收缩，这是一种有效地面部按摩，会使脸部更有弹性，也可以阻止面部线条下垂。可惜，人到成年，（80），比孩提时代每天笑400 次左右少多了。对健康来说，这真是令人遗憾的损失。",
