        "passageZh": "一位心理医生在银行排队取款时，看到前面有一位老先生满面愁苦。这位心理医生暗想，我要让他开朗起来。于是一边排队一边寻找老先生的优点，终于他看到，老先生虽然年近70，驼背哈腰，却长着一头漂亮的金发。当这位老先生办完事情走过心理医生身边时，心理医生衷心地赞美道：“先生，您的头发真漂亮！”老先生一向以一头漂亮的头发而自豪，听到心理医生的赞美，非常高兴，顿时变得开朗起来，挺了挺腰，道声谢后哼着小曲走开了。可见，一句简单的赞美能给别人带来很大的快乐。在一次心理咨询中，我碰到一位女大学生，她因为宿舍中的人际关系紧张而苦恼。在宿舍里，同学们互不来往，各自忙着自己的事情，似乎相互都有戒心，很难知心交谈，宿舍气氛沉闷。她希望改变这种状况，但又不知从何做起。我告诉她：从自己开始，试着夸奖他人，真心赞赏他人，如：“你今天气色很好！”“你的眼睛真亮！”“这条裙子对你再适合不过了！”等等。不久以后，她来告诉我，宿舍的气氛完全变了样，大家相互帮助，彼此关心，在一起时有说有笑。下课后都愿意回宿舍，好像宿舍有一种无形的吸引力。善于赞赏别人常会使一个领导者具有神奇的力量。如果你对下属说：“大家知道，你是很能干的，最近单位人力紧张，我们希望得到你的帮助，辛苦你了。”这样一来，你的下属不会不为你分忧，即使一人干了两个人的活儿也不会有什么怨言。",
