        "kind": "mcq",
        "passageZh": "今天你穿什么颜色的衣服？即使在你的印象中只是顺手拿起了一件还算顺眼的衣服，事实上，这可能并非“偶然”，你对衣服的选择已经反映出你今天的精神状态。“颜色影响人的情绪、健康和状态”这一论点由来已久。人们早就针对不同的疾病症状，将病房涂上不同的颜色。一旦诊断出病人所需的颜色，他们就被安置在一个对应颜色的房间，因为这样有助于病人恢复健康。世界各地都有类似的“颜色”疗法。运用颜色还可以影响人们的行为方式，比如说，快餐厅往往采用明快的红色，这样能够调动食欲，并且加快进餐的速度。颜色影响着人体的很多机能，比如说食欲、睡眠以及体温。颜色还能引发不同的心理反应，因为我们的情绪往往受“颜色记忆”的影响。如果对某种颜色有不好的记忆，下次看到这种颜色时就会很不舒服。同样，如果某种颜色带给你的是美好的回忆，再看到这种颜色时会让你心情舒畅。专家指出：“其实颜色对我们影响至深，看到喜欢的颜色，我们会感到舒适和宁静。相反，不喜欢的颜色则让人很不舒服。也就是说，服装的颜色和周围环境的颜色会影响我们的情绪。”当情绪低落、过分紧张的时候，人们会不自觉地选择一些颜色暗淡的衣服，其实此时反而应该选择明亮的红色、桔黄色或者温暖的黄色，这样有助于情绪的改善。",
