        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "潘家园本是北京一个不太知名的地方，近年来随着“潘家园”古玩市场的红火，这里成了收藏爱好者“淘宝”的好地方，潘家园的名字开始家喻户晓。潘家园在解放前只是北京城外一个小小的村落，当时被称为潘家窑。早年间在护城河东边有不少砖窑瓦场，潘家窑是其中的一家，因窑主姓潘，于是窑场以窑主的姓氏而得名。据传这潘窑主是山东人，年过五旬，原是烧琉璃瓦出身。当初来到这里，他本想开家烧制琉璃瓦的窑场，但因这里土质疏松，不宜烧制琉璃瓦，于是改烧小方砖。当时这一带有七八家砖窑，彼此竞争很激烈，潘窑主初来乍到，又是改行烧砖的，所以生意一直不好。但他不想放弃，因为他看准了这里临近京城，地理位置好。于是他私下里在各个窑场转了几天，回来后就有了主意，一是要提高砖的质量，二是在经营上下工夫。首先他严格把好每一块砖的烧制环节，绝不偷工减料，所以烧出的砖成色好，光洁度高，硬度很强，不易破碎。同时在销售上，他也比别人技高一筹，当时卖砖是以“丁”为单位，一“小丁”砖是200块，一“大丁”砖是800块，但他在码砖时，一“小丁”要码220块，一“大丁”要码850\n块——价格上与别的窑场差不多，可数量上却暗自比别人多。同时又雇了三辆马车，凡买主在十里地之内的，一律免费送砖上门。不到一年的工夫，潘家窑场就红火起来，并很快出了名，甚至连一二百里地以外的人也慕名来他这里买砖。于是这潘家窑场越开越大，而另外几家窑场因经营不善相继关了张。后来在潘家窑场附近形成村落，便依窑场之名，得名潘家窑。到了民国后期，这一带的土被用得差不多了，只留下许多大水坑和洼地，再取土烧砖很是困难，于是潘家窑暂时关闭，不久便迁到了房山一带。上个世纪60年代以后这里开始建设居民区，并以“潘家窑”之名而称。但叫了没有多久，人们就觉得不雅，就改为“潘家园”，这个“园”字，便是“家园”的意思，并将附近新修的道路称为潘家园路。",
