        "passageZh": "山峦重叠、翠岗起伏、佳木葱郁、云海飘浮的名山，往往出产名茶，如黄山毛峰、武夷岩茶、庐山云雾等，都列为茶中上品，畅销国内外。为什么高山上生长的茶叶质量特别好呢？这与高山上的空气、光照、温度、土壤等自然环境有关。我们知道，山越高，空气就越稀薄，气压也就越低。茶树在这样的环境里生长，水分的蒸腾相应地加快了。为了减少水分的蒸腾，茶叶本身不得不形成一种抵抗素，来抑止水分的过分蒸腾，这种抵抗素就是茶叶的宝贵成分“芳香油”。同时，高山一年四季常常云雾弥漫，如庐山平均每年有188.1 天为有雾日。因为有雾，茶树受到太阳光直射的时间较短，光照较弱，这正好适合茶树的耐阴习性。由于高山有雾的天气多，空气湿度就比较大，这样长波光被云雾挡了回去，照不到植物上，但短波光透射力强，却可以透过云层照射到植物上。这种短波光的照射，有利于茶叶芳香物质的合成。种植在高山上的茶叶香气比较浓，就是这个道理。其次，高山地区昼夜温差大，山高温度低，对茶叶生长也是一个有利条件。气温低，茶叶生长速度慢，有利于茶叶内的成分，如单宁酸、糖类和芳香油等物质的积累和保存。还有一点是，高山栽茶的地方大部分为沙质土壤，土层深厚但透气良好，酸碱度适宜，加上树木葱郁，落叶多，土壤肥沃，有机质丰富，这也是适宜于茶树生长和茶叶质地优良的一个因素。",
