        "type": "mcq",
        "prompt": "Nghe đoạn câu 16 và chọn đáp án đúng: 关于父亲，下列哪项正确？",
        "statement": "",
        "statementPy": "",
        "audioZh": "男：梁女士您好！您一直强调家庭教育的重要性，那么能跟我们说说您在青少年时代受到的家庭教育吗？ 女：我是在南方长大的，父亲是一家报社的副刊部主任，他曾经出过一本中篇小说集。母亲不写东西，但爱读书，我们家庭的文化气息很浓。应该说我是在一个比较好的环境中成长的。我本来可以成为一个作家的。我父亲也希望我将来能走他的路，从事他的事业，做一个文化人。在这样的一个家庭中，如果确立理想的话，向文化方面发展是比较适合我的。但虽然我尊重作家，要让我把它确立为将来的事业我不愿意。 男：大概是看到父亲每天爬格子挺辛苦的，有一种畏惧感吧？ 女：不是。我记得我母亲说过一句话，她说：“女儿，你要是学文学，你爸爸会帮你很大的忙。”母亲的话是出于一种关心，她可能是不想我多走弯路，但就这句话使我产生了一种逆反心理。我想，我的事业干嘛非要爸爸帮我呢？出于这种逆反心理，我决定要走一条与父亲截然相反的路。 男：为这件事，父母一定很失望吧？您和他们发生过冲突吗？ 女：那时候父母有些失望，但他们并没有强迫我的意思，我们家还是比较民主的。当然父母对我的影响真是很大，这不仅仅表现在我现在很喜欢文学和艺术，而且那种文化的氛围给了我气质上的影响。无论我从事什么职业，气质上总是浸染着很多来自家庭的东西，这是变不了的。 男：依您看，您的家长是合格的吗？ 女：家长合格不合格主要是看他是不是真正关爱自己的孩子，能不能引导孩子朝着一个正确的方向发展，能不能从人本的角度平等地对待孩子，能不能开发孩子的所有潜力。我认为我父母是合格的家长。 问：关于父亲，下列哪项正确？",
