        "audioZh": "从前，有个人偷了一袋洋葱，被人捉住后送到法官面前。法官提出了三种惩罚方案，让这个人自行选择。第一种方案是一次性吃掉所有的洋葱；第二种是鞭打一百下；第三种是交纳罚金。这个人选择了一次性吃掉所有的洋葱。一开始，他信心十足，可是吃下几个洋葱之后，他的眼睛像火烧一样，嘴巴像火烤一般，鼻涕不停地流。他说：“我一口洋葱也吃不下了，你们还是鞭打我吧。”可是，在被鞭打了几十下之后，他再也受不了了。他哭喊道：“不能再打了，我愿意交罚金。”后来，这个人成了全城人的笑柄。因为他本来只需要接受一种惩罚的，却将三种惩罚都尝遍了。其实，许多人都有过这样的经历，由于对自己的能力缺乏足够的了解，导致决策失误，而尝到许多不必要的苦头。 问：那个人为什么要被惩罚？",
