        "prompt": "Nghe đoạn câu 34 và chọn đáp án đúng: “实在让人为他们捏了一把冷汗”主要是什么意思？",
        "statement": "",
        "statementPy": "",
        "audioZh": "《动物世界》中的大多数镜头都是动物学家在野外实地拍摄的，这些冒险家有时披着人造河马皮混入河马群，有时单枪匹马深入婆罗洲探寻巨大的食人蟒，实在让人为他们捏一把冷汗。好在科学家有一个好助手——隐蔽的摄像机，可以近距离拍摄动物而不引起动物的警觉。这种摄像机隐藏在伪装成石头、树木、动物粪便等仿造物里，它们被事先放置在动物经常出没的地方，一旦动物出现，拍摄信号会自动传输到计算机上。这种摄像机装有声控开关，平时不工作，一有动物的声响，就自动启动。还有一种叫做“魔镜”的伪装摄像机，非常适合在热带森林里拍摄。它是一辆装有履带的小车，可以远程遥控，履带可以爬坡，适合在不平的路面行动。这辆小车四面都是镜子，无论从哪个角度看过去，都能反射周围的景物，和森林混在一起很难被动物们发现。这种摄像机避免了拍摄时打扰动物，也保证了拍摄人员的安全。 问：“实在让人为他们捏了一把冷汗”主要是什么意思？",
