        "passageZh": "新疆有两种著名的树，一是白杨，一是胡杨。白杨的美在于挺拔，而胡杨之美在于顽强的生命力和醉人的金黄色，因此更令人神往。据说，（76），是一种古老的树。随着时间的推移，胡杨逐渐演变成沙漠河流沿岸最主要的树种。为了能在缺水的环境中生存，胡杨的根系非常发达，它们的根可以扎到地下几十米去吸取水分。每年4 月，胡杨开花结果，（77），如同一小段一小段绿色的鞭炮，挂满枝头。这些果实其实是花苞，花苞会慢慢地从绿色变成淡红色，六七月份的时候，花苞就炸开了。风一吹，成熟了的种子随风飘浮，（78），成长为一棵顶天立地的胡杨树。每年10月，秋天的胡杨就穿上金黄色的礼服，（79）。远观胡杨，层林尽染，一片金色的海洋。近观胡杨，每一片叶子的叶脉都清晰可见，透明的叶片相互映衬，散射出黄色的光晕。在新疆塔里木河两岸生长着的那些或高或低、错落有致的胡杨，每年都吸引着许多游客来到这里。有人说，正是有了这片胡杨林，（80）。所以，当地人视胡杨为“英雄树”，还有人赞美它是“沙漠的脊梁”。",
        "passagePy": "",
        "passageVi": "",
