        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "有时，我们问从外地旅行回来的人对当地的印象，不同人的回答常常是不同的，而且差距很大。如果是你，会相信谁的说法？他们说的可能全都正确，也可能全都是错的。他们可能会将自己偶然的印象曲解为一般的状况，这也是我们日常生活中的误会、偏见等不正确看法所产生的原因。例如，我们到餐厅吃饭，如果有一次遇到服务员无礼的对待，就会认为所有的服务员都如此，从而给予一般化的解释：“现在的服务员越来越没有敬业精神了。”而且，只要有一次这样的印象，对其他的印象都会产生抵触感。片面的印象越来越强烈，行为倾向也更加明显，最后可能成为坚定的信念，进而对所有服务员产生偏见。一般而言，偏见是指人们观念、想法的固定化，就如同小孩从小被灌输某种观念，长大后这种观念还会依然存在。若对这种偏见追根究底，其源头很可能是一个人的曲解。因此，有些“例外”被视为了一般的情况，而“一般”的情况也会被当成例外。有权威主义倾向的人，较易产生偏见与曲解，这些人对自己既有的印象相当顽固，拒绝做任何改变，而经常主观地说：“现在的老师„„”或“最近的小孩„„”。我们在接受某个观念之前，应先分清一般与例外的情形，否则就很容易掉入陷阱。",
