        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "纸币的出现是货币史上的一大进步。北宋时期四川成都的“交子”则是真正纸币的开始。据专家考证，“交子”最早是以私下流通的形式出现的，所以又称“私交子”。随着商品经济的发展，“交子”的使用范围越来越广泛。许多商人联合成立专营发行和兑换“交子”的交子铺，并在各地设交子分铺。由于交子铺户恪守信用，随到随取，而所印“交子”图案讲究，隐作记号，黑红间错，亲笔押字，他人难以伪造，所以“交子”赢得了很高的信誉。为了避免铸币搬运的麻烦，商人之间的大额交易，直接用“交子”来支付货款的事例日渐增多。正是在反复进行的流通过程中，“交子”逐渐具备了信用货币的功用。之后，有统一面额和格式的“交子”，开始作为一种新的流通手段向市场发行。这种“交子”已经是铸币的符号，成了真正的纸币。但此时的“交子”尚未取得政府认可，还是民间发行的“私交”。由于并非所有的交子铺户都是守法经营、恪守信用的。有一些唯利是图、贪得无厌的铺户，恶意欺诈，在滥发“交子”之后闭门不出，停止营业；或者挪用存款，经营他项买卖失败而破产，使所发“交子”无法兑现。这样，当存款者取钱而不能时，便往往激起事端，引发诉讼。于是，北宋景德年间（公元1004-1007\n年），当地政府对交子铺户进行了整顿，剔除不法之徒，指定由16 户富商经营。至此，“交子”的发行第一次取得了政府的认可。",
