        "passageZh": "进行一次网络搜索需要付出怎样的代价？这个问题很多人大概从未思考过，因为利用“百度”等进行搜索是不需要付费的。实际上，网络搜索其实是需要付出代价的，而且这个代价不能只用金钱去衡量。“搜索引擎”这个词太妙了。引擎就是发动机，你要将它发动起来，显然离不开能源或电力。网络搜索需要数百万台计算机协同作战才能完成。通过联网，这些被放置在机房内的计算机形成一个单独的系统。这个系统要遵守热力学定律，因此也会消耗能源。工作需要消耗能量，像推动硅片上的电子这样微不足道的工作也是如此。另外，没有一个引擎是完美无缺的，也就是说，输入的一些能量最终会以热量的形式消失。一个成功的搜索结果页面，需要具备清楚和有序这两个条件。要提供理想的搜索结果，服务器群必定会忙得一团糟。硅原子的热运动搅动电脑中央处理器支架后面的空气分子并对其加热。为了驱动计算机风扇以及将热量赶出仓库的空调，我们还需消耗更多的能量。不管搜索什么，最后都归结为同样的工作过程：移动原子后再冷却。所有这些步骤均需要消耗能量。据统计，每台服务器每小时消耗大约1000 瓦的电量，一个拥有100 万台服务器的搜索引擎，每小时就会消耗100 万千瓦的电量。这个搜索引擎每小时产生近1000 万个搜索结果，每次搜索消耗的能量可以让一只100 瓦的灯泡工作一个小时。如果全球60 多亿人都使用搜索服务，那将会消耗多少能源？我们一定都听过这样的观点：“云计算”将成为信息架构的未来。但未来等待我们的，可能是一块巨大的“二氧化碳云”。",
