        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "一天，胡雪岩正在客厅里和几个分号的大掌柜商谈投资的事情。谈到最近的几笔投资，有的掌柜经营不善，胡雪岩紧绷着脸，教训起其中几个在投资中失利的掌柜。胡雪岩话音刚落，外面便有人禀告，说有个商人有急事求见。前来拜见的商人满脸焦急之色。原来，这个商人在一个生意中栽了跟头，急需一大笔资金周转。为了救急，他拿出自己全部的产业，想以非常低的价格转让给胡雪岩。胡雪岩让商人第二天来听消息，自己连忙吩咐手下人去打听是不是真有其事。手下人很快赶回来，证实那个商人没有说谎。胡雪岩听了以后，连忙让钱庄准备银子，又从分号急调了大量现银。第二天，胡雪岩将那个商人请来，不仅答应了他的请求，还按照市场价来购买对方的产业，这个数字大大高于对方转让的价格。大家都惊愕不已，不明白胡雪岩为什么连到手的便宜都不占，却要坚持按市场价来购买那些房产和店铺。胡雪岩看了看疑惑的人们，讲了一段自己年少时的经历：“我还是一个小伙计时，东家常常让我拿着账单四处催账。有一次，正在赶路的我遇上大雨，同路的一个陌生人被雨淋湿。那天我恰好带了伞，便帮人家打伞。后来，下雨的时候，我就常帮一些陌生人打打伞。时间一长，那条路上的很多人都认识我了。有时候，我自己忘了带伞也不用怕，因为会有很多我帮过的人为我打伞。”说着，胡雪岩微微一笑：“你肯为别人打伞，别人才会愿意为你打伞。那个商人的产业可能是几辈人积攒下来的，我要是以他开出的价格来买，当然很占便宜，但是人家可能就一辈子翻不了身。这不是单纯的投资，而是救了一家人，既交了朋友，又对得起良心„„谁都有雨天没伞的时候，能帮人遮点儿雨就遮点儿吧。这也是我下雨时即使不带伞也不会被淋湿的妙法啊。”",
        "passagePy": "",
        "passageVi": "",
        "q": "那个商人求胡雪岩帮他什么忙？",
