        "sourceTitle": "Văn bản gốc đề thật H61111",
        "sourceZh": "小王是一名刚刚毕业的大学生，参加了好几次人才招聘会，投出去的简历不计其数，却都石沉大海。一天，他无意中在晚报上看到一则招聘启事，一家玻璃制品公司招聘一名销售主管，开出的待遇相当诱人。抱着试试看的心态，小王来到这家公司，一问才知道，应聘这家公司的销售主管是有条件的，那就是必须把公司库存的一万个鱼缸销售出去。这些鱼缸原是一家销售水族品的公司订购的，年初，那家公司的老板因为炒股破了产，于是这些做工精良的鱼缸便成了积压货。原来公司招聘销售主管是假，销售积压的货物才是真。一个初涉世事的年轻人，到哪儿去找这样的销售渠道呢？无奈之下，小王只得沮丧地回了家。不久后的一天，小王和几个朋友到郊外野炊。他们来到一片叫做“荷花池”的池塘边，朋友们尽情嬉戏，小王则望着湖面发呆。忽然，一个大胆的想法冒了出来。结束野炊活动的第二天一大早，小王兴冲冲地来到那家玻璃制品公司。他说自己有办法把厂里积压的一万个鱼缸销售出去，前提是公司必须预付给他\n3000 元的经费。看到小王很有信心，而且所要的经费又不多，公司老总极为爽快地答应了。小王拿着公司预付的3000 元经费，离开了那家公司，不知去向。正当人们议论小王是不是骗子的时候，一个意外的消息在当地不胫而走——郊外的那片叫做荷花池的池塘里，一夜之间忽然冒出成千上万条漂亮的金鱼来。这事儿简直太稀奇了，许多市民纷纷前往观看。由于荷花池是一片开放的水域，无人管理，于是很多人便不辞辛苦地亲自挽起裤腿儿下去捉鱼。孩子笑了，大人也笑了，大家像得了战利品似的，把捞来的鱼带回家养在鱼缸里观赏。鱼缸的需求量一夜之间猛增。很快，市区水族馆的金鱼缸便销售一空，最大的赢家无疑是那家玻璃制品公司，积压了几个月的产品一夜之间竟然成了抢手货，价钱也因此翻了一番。公司老总高兴得合不拢嘴，他说，自己之所以如此兴奋，不仅仅是因为积压的库存成了抢手货，更重要的是，自己得到了一个非常难得的销售人才。因为他知道，这一池的金鱼绝不会像大家传言的那样是从天上掉下来的，而是自己预付给小王的\n3000 元钱运作的结果。最终，小王理所当然地得到了销售主管的位置。生活中，常常有人感叹自己不够幸运，看着别人创造出一个又一个奇迹，总是羡慕至极却又无可奈何。事实上，奇迹的产生并非偶然，奇迹缘于创造，缘于细心的观察与发现。许多时候奇迹的出现很简单，只不过是一个有心人在一个司空见惯的事物上加上了一份丰富的想象力而已。",
