        "statement": "",
        "statementPy": "",
        "audioZh": "女: 篮球会是你的终身事业吗？你将来会从事哪些方面的工作？男: 可以肯定地说，我将来的事业轨迹一定是和体育有关系的。因为体育是包含很广泛的领域，我希望将来可以起到一个纽带的作用，用自己的能力去做一些事情。 女：什么原因促使你成立自己的基金会？ 男：在此之前我一直在通过各种方式参与公益活动，我希望能够帮助更多失学的孩子，让他们有条件更好地成长。同时这个基金也关注其他一些自然灾害和社会问题的受众。这也是金钱最具有意义的流向和方式。 女：作为世博会大使，你参与了哪些有意义的推广活动？你是如何向外国朋友推广世博会的？ 男：我很荣幸能为自己的家乡和家乡人们出一份力。我参与了“明星带你看世博”大型公益活动、美国花车巡游等等。这次世博会是历史上最大规模的一次展会，作为上海人我会把这里最具特色、新鲜有趣的一些东西介绍给外国朋友们，除了看世博场馆，我希望他们都能去看看东方明珠塔、城隍庙、豫园和外滩，尝尝这里的小笼包、大闸蟹。 女：你对于世博会的场馆熟悉吗？对哪些场馆最感兴趣？ 男：中国馆非常有特色，我很喜欢，同时我有机会的话希望去非洲馆看看，我还没有去过非洲，想去看看非洲的原生态。 女：你如何看中国和上海的未来？ 男：上海作为一个商业城市，它的机会越来越多，会有更大的发展。同时对于中国的未来我也保持比较乐观的态度，但是由于国家太大，在快速发展的过程中，危险与机遇并存。 女：你怎样规划自己未来的五年？ 男：首先我希望先学习做一个父亲，我现在经常会回想起自己小时候，我的爸爸是怎么培养我、教导我的。养育一个孩子其实并不是件容易的事情。同时，我也会好好打球，创造好的成绩，同时在学习中巩固国内的事业。 问：男的为什么要成立基金会？",
