        "statement": "",
        "statementPy": "",
        "audioZh": "女：作为一个访谈节目主持人，你在采访人物时，立足于挖掘人物的哪方面特点？ 男：发掘嘉宾人生中的闪光点和可以让人感动的人生体验，不管是失败的，或者成功的。然后，让嘉宾用讲故事的方式演绎出来，使听者觉得可思、可学、可追，从中获得教益。 女：采访中，如何才能更快地拉近与被采访对象之间的距离，有何准备工作？ 男：事先做充分的资料准备工作，尽可能和嘉宾预谈一下，和嘉宾事先沟通，了解嘉宾的思想、表达能力，让嘉宾也事先了解节目，知道这个节目需要谈什么。这样能使自己和嘉宾都能有一种互动，也能使节目有别于其他媒体的访谈节目。 女：在主持和采访中，突发事件在所难免，是怎样处理的？ 男：作为直播节目来说，各种意想不到的事情是每天发生的，只是大小不同而已，关键在于看自己的准备工作是否充分、交谈中话题走势的预判能力、嘉宾听众的情绪变化的把握能力等等，有些是需要短期内准备的，有些是需要长期积累的。 女：在主持的过程中，是否也有懈怠的时刻？如何使自己一直保持着工作的激情？ 男：在工作中有疲劳的时候，也有觉得踯躅不前的时候，但没有懈怠过。因为我对工作的态度从来没有改变过。我很喜欢一句话——态度决定一切。从事这个职业是我自己的选择，坚守这个职业，也是自己的决定。如果你喜欢某一个职业或者事业，你自然会充满激情和创造力。此外要懂得欣赏自己的工作。尽自己所能，将自己的节目做成一档受听众喜欢的节目，这同样也是自己工作的动力。 女：工作之余，采取哪些方式来给自己充电？ 男：读书、看报、看杂志、看电视新闻、上网浏览，读一些业内新闻、同行的文章，等等，并不刻意采用一种固定的充电模式。但对所有的资讯都保有一种职业的敏感，保持一种学习的态度。 问：男的让嘉宾用哪种方式演绎人生体验？",
