        "passageZh": "任何事情都可能触发白日梦：一句话，一个场景，或是一段文字……白日梦瞬起忽灭，（71）。通常人们都认为白日梦浪费时间，而心理学家的观点并非如此。研究发现，人们的精神活动有一半儿时间会花在白日梦上，它会帮助我们实现自己的目标，揭开内心深处的希望和恐惧。这听上去似乎自相矛盾，人们都以为白日梦是胡思乱想，但实际上，它的作用之一就是提前规划我们的生活，（72），帮助我们熟悉新的环境，给未来做计划。至于白日梦中经历的虚构的负面事件，并不会让我们产生忧虑，（73），检验一下如何能做得更好，带来更多的可能性。有时候，白日梦本身就会产生治疗的效果。就像在脑海中过电影一样，做梦者也能改变自己的心情。白日梦能令人放松，让我们开心。（74），可以帮助我们应付现实生活中难以克服的局面。所以，（75）。在阳光明媚的街头小店，喝着咖啡，任由心灵在幻想的天空无拘无束地翱翔，不但有趣，而且有益。",
        "passagePy": "",
        "passageVi": "",
