        "passageZh": "长者带领村民日夜兼程，要把盐运送到某地换成大麦过冬。一天晚上，他们露宿于荒凉的野外，星空浩渺，（76），取出三粒盐块投入营火，占卜山间天气的变化。大家都在等待“天气预报”：若听到火中盐块发出“霹雳啪啦”的声响，那就是好天的预兆；若是毫无声息，那就预示天气即将变坏，风雨随时会降临。长者神情严肃，因为盐块在火中毫无声息。他认为不吉，主张天亮后马上赶路。但族中另一位年轻人认为“以盐窥天”是迷信，（77）。第二天下午，（78），风雪交加，坚持晚走的年轻人这才折服于长者的睿智。其实，用今天的科学解释，长者也是对的，（79），与空气湿度相关。换句话说，当风雨临近时，湿度高，盐块受潮，投入火中自然喑哑无声。事实上，长者的智慧总是藏在长年累月的积淀中，它历经时光的风雨，渗透在我们的生活之中。（80），然而就像从海水中提炼的盐块一样，它们依然是对大海深远记忆的结晶。",
