        "passageZh": "一位棋道高手退下来后被聘为教练。他培训年轻选手的方式十分特别。他不教年轻棋手们怎么样去进攻别人，也不教如何运用谋略，他和徒弟们天天对弈，决出输赢后，让徒弟们仔细推敲他们的每一步落子。找出失误多的，他就表扬；找出失误少的，他就十分严厉地批评。时间长了，那些年轻棋手们纷纷有了意见，大家都说他的教棋方式太单调，缺乏令人信服的理论深度。不传谋略，不传技巧，只让棋手自察失误，怎么能培养出一流高手呢？面对种种疑问，他依旧我行我素。有时，他只给他们一个简单的提醒，更大的失误，都让年轻棋手们自己去发现。刚开始时，每局对弈下来，每个棋手都能找出自己的诸多失误，甚至许多人觉得自己简直是个臭棋篓子。但天长日久，那些棋手的失误越来越少，有的甚至一局对决下来竟没有一次失误。这个时候，选手们开始向他要求：“给我们传授点儿理论和技巧吧，对弈，毕竟是要取胜于别人，不是自己和自己决胜负，没有谋略和技巧怎么行呢？”他微微一笑：“一个对弈高手，最大的技巧就是能够发现自己的破绽，最高的谋略就是能够避免自己的失误。”后来，他培训的选手参加大赛，将很多高手击败。那些高手惊讶不已，个个摇着头叹息说：“这些年轻选手太厉害了，虽说他们没有什么技巧和谋略，但我们丝毫找不到他们的破绽和失误，他们赢就赢在没有失误。”获胜之后，那些年轻选手欣喜若狂地向教练报喜。他说：“一个棋手能否赢得别人，技巧和谋略都无关紧要，最重要的是他要赢得自己，杜绝自己的失误。没有失误就没有破绽，任何人都对你束手无策。”自己的失误，往往成为对手击败自己的机遇。许多时候，我们并不是败于自己的弱小，而是败于自己的失误。",
