        "partLabel": "Phần 4 • Đọc hiểu văn bản dài chọn đáp án (81–100)",
        "kind": "mcq",
        "passageZh": "章鱼是一种可怕的海洋食肉动物，以捕食小鱼虾为生。由于没有脊椎，章鱼的身体异常柔软，它们能够像流水一样随意把自己变成什么形状，这为它们的捕食活动提供了极其便利的条件。比如，它们常把自己塞进一个小小的海螺壳里，等到鱼虾一靠近，它们就迅速探出头来捕获猎物，然后就开始美美地享用了。你可不要觉得这是一件很轻松的事情，因为我还没告诉你章鱼有多大。据说，最大的章鱼体重可达70 磅，也就是64 斤左右，相当于半袋水泥，或者是一个10 来岁少年的体重。想想如此巨大的身体，居然可以随心所欲地钻进任何一个它想去的地方，甚至可以从一个银币大小的洞里钻进钻出，这不能不说是一个奇迹。那么，如此危险又如此灵活的章鱼是不是总会无往不胜呢？答案是否定的，因为如果遇到聪明的渔民，它就只有变成傻瓜的份儿了。这是怎么回事？原来，熟悉章鱼习性的渔民会让章鱼自己囚禁自己——他们把用绳子系好的小瓶子垂进海里，吸引着海底的章鱼们往里钻。正如他们所想，那些“聪明”的章鱼往往会争先恐后地钻进瓶口，不管里面的空间多么小、多么窄。这样一来，原本在海洋里神出鬼没的章鱼用不了几分钟就会变成小瓶子的囚徒，而渔民自然就可以“坐收渔利”了。是什么囚禁了章鱼？是瓶子吗？当然不是，囚禁章鱼的，是它们自身的习惯，或者说是它们的思维定式。它们只晓得狭窄的地方可供自己捕食，所以一见到小洞，就会拼命往里钻，而不管那是一个牛角尖，还是一条死胡同。如果这种思维定式的主人是一个人，结果又会如何呢？当遭遇不如意或者死胡同时，及时减速绕行才是明智之举，才可能为自己赢来更广阔、光明的天地。倘若固执向前，只会让自己的前路越来越狭窄，甚至失去前路。",
